1252	\end{lemma}
1253	\begin{proof}
1254		\leanok
1255		\uses{def:graph-distribution}
1256		The distribution $\mu_G$ is uniform on the set of ordered pairs $(u,v) \in U \times U$ with $\{u,v\} \in E$, and that set is nonempty because $E$ is: an edge $\{u,v\} \in E$ yields the ordered pair $(u,v)$. A uniform distribution on a nonempty finite set has total mass one.
1257	\end{proof}
